// One visual key shared by globe, filters and relationship cards.
export const relationStyles={political:{color:'#80d6a6',dash:[6,2,1,2],label:'Политические объединения'},trade:{color:'#59d8e8',dash:[],label:'Торговля и обмен'},colonial:{color:'#ff9b82',dash:[7,5],label:'Колониальная зависимость'},cultural:{color:'#d9bd72',dash:[10,3],label:'Знания и культура'},diplomatic:{color:'#baa5ff',dash:[3,4],label:'Дипломатия и сотрудничество'},material:{color:'#84b4f5',dash:[1,4],label:'Перемещение материалов'}};
export function relationStyle(type){return relationStyles[type]||{color:'#b9a5ff',dash:[3,3],label:'Связь'};}
// A search selects connected relationships; keep both endpoints visible.
export function relationNetwork(cultures,relations,seedIds){const byId=new Map(cultures.map(c=>[c.id,c]));const links=relations.filter(r=>byId.has(r.from)&&byId.has(r.to)&&(!seedIds||seedIds.has(r.from)||seedIds.has(r.to)));const ids=new Set(links.flatMap(r=>[r.from,r.to]));return {links,nodes:cultures.filter(c=>ids.has(c.id))};}
export function relationNodeColor(id,links){const types=new Set(links.filter(r=>r.from===id||r.to===id).map(r=>r.type));return types.size===1?relationStyle([...types][0]).color:'#f2f6ff';}
export function segmentDistance(p,a,b){const dx=b[0]-a[0],dy=b[1]-a[1],length=dx*dx+dy*dy;const t=length?Math.max(0,Math.min(1,((p[0]-a[0])*dx+(p[1]-a[1])*dy)/length)):0;return Math.hypot(p[0]-a[0]-t*dx,p[1]-a[1]-t*dy);}
// Keep network waypoints separate from authored culture/state essays.
export function mergeRelationAtlas(history,atlas){const ids=new Set(history.cultures.map(c=>c.id));const cultures=(atlas.cultures||[]).map(c=>{if(ids.has(c.id))throw Error('Duplicate culture: '+c.id);ids.add(c.id);return {...c,relationOnly:false};});const nodes=atlas.nodes.map(n=>{if(ids.has(n.id))throw Error('Duplicate network node: '+n.id);ids.add(n.id);return {...n,relationOnly:true,government:'',society:n.summary,economy:'',religions:['na'],rulers:[],events:[],aliases:n.aliases||''};});return {...history,cultures:[...history.cultures,...cultures,...nodes],relations:[...history.relations,...atlas.relations],sources:{...history.sources,...atlas.sources}};}
export function relationFields(type){return type==='political'?['Структура отношений','Условия участия','Последствия']:type==='cultural'?['Что передавалось','Как взаимодействовали','Последствия']:type==='diplomatic'?['Контакт и договорённости','Обязательства и условия','Последствия']:type==='material'?['Материал и находки','Что известно о передаче','Что можно заключить']:['Что отправляли','Встречный поток и контроль','Выгоды и издержки'];}
// Parallel relationships remain individually visible and selectable.
export function relationLane(link,links){const same=links.filter(r=>r.from===link.from&&r.to===link.to||r.from===link.to&&r.to===link.from).sort((a,b)=>a.id.localeCompare(b.id));const i=same.findIndex(r=>r.id===link.id);return (i-(same.length-1)/2)*10*(link.from<link.to?1:-1);}
export function projectedRelation(interpolate,project,isVisible,lane){const points=[];for(let i=0;i<=72;i++){const t=i/72,coord=interpolate(t);if(!isVisible(coord)){points.push(null);continue;}const p=project(coord),a=project(interpolate(Math.max(0,t-.005))),b=project(interpolate(Math.min(1,t+.005))),dx=b[0]-a[0],dy=b[1]-a[1],length=Math.hypot(dx,dy)||1,offset=lane*Math.sin(Math.PI*t);points.push([p[0]-dy/length*offset,p[1]+dx/length*offset]);}return points;}
